descriptor.templateCss:
.trend-card-container.solar {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  background: linear-gradient(160deg, rgba(14, 25, 16, 0.95) 0%, rgba(8, 15, 9, 0.98) 100%);
  border-radius: 10px;
  border: 1px solid rgba(100, 184, 86, 0.22);
  border-top: 3.5px solid #F59E0B;
  padding: 12px 18px 10px 18px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
}
.trend-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.trend-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.6px;
  color: #94a3b8;
}
.trend-icon { font-size: 16px; }
.trend-badge {
  font-size: 11px;
  font-weight: 700;
  padding: 2px 10px;
  border-radius: 20px;
  color: #F59E0B;
  border: 1.5px solid #F59E0B;
  background: rgba(245, 158, 11, 0.12);
}
.trend-kpi-bar {
  display: flex;
  justify-content: space-around;
  align-items: center;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(100, 184, 86, 0.12);
  border-radius: 8px;
  padding: 5px 12px 6px 12px;
  margin: 6px 0 4px 0;
}
.kpi-col {
  display: flex;
  flex-direction: column;
  align-items: center;
}
.kpi-lbl { font-size: 10px; font-weight: 700; color: #64748b; letter-spacing: 0.5px; }
.kpi-val-group { display: flex; align-items: baseline; gap: 4px; }
.kpi-num { font-size: 19px; font-weight: 800; line-height: 1.1; }
.kpi-unit { font-size: 12px; font-weight: 600; color: #94a3b8; }
.kpi-sub { font-size: 10px; font-weight: 600; color: #94a3b8; margin-top: 1px; letter-spacing: 0.3px; }
.kpi-divider { width: 1px; height: 32px; background: rgba(148, 163, 184, 0.15); }
.chart-wrapper {
  width: 100%;
  flex: 1;
  min-height: 140px;
  position: relative;
}
.trend-footer {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: #64748b;
  border-top: 1px solid rgba(148, 163, 184, 0.12);
  padding-top: 4px;
  margin-top: 2px;
}

descriptor.controllerScript:
self.onInit = function() {
  self.initChart();
  self.setupHoverSync();
  self.onDataUpdated();
};


self.ensureEcharts = function(cb) {
  if (window.echarts) {
    cb();
    return;
  }
  var existing = document.querySelector('script[src*="echarts"]');
  if (!existing) {
    var s = document.createElement('script');
    s.src = '/echarts.min.js';
    s.onload = cb;
    document.head.appendChild(s);
  } else {
    existing.addEventListener('load', cb);
    var attempts = 0;
    var intv = setInterval(function() {
      attempts++;
      if (window.echarts || attempts > 50) {
        clearInterval(intv);
        if (window.echarts) cb();
      }
    }, 100);
  }
};

self.initChart = function() {
  var container = self.ctx.$container ? (self.ctx.$container[0] || self.ctx.$container) : null;
  if (!container) return;
  var el = container.querySelector('#echarts-solar-bess');
  if (!el) return;

  self.ensureEcharts(function() {
    if (!self.myChart && window.echarts && el.clientWidth > 0 && el.clientHeight > 0) {
      self.myChart = window.echarts.init(el);
      if (self.onResize) self.onResize();
      if (self.onDataUpdated) self.onDataUpdated();
    } else if (!self.myChart && window.echarts) {
      setTimeout(function() {
        if (!self.myChart && el.clientWidth > 0 && el.clientHeight > 0) {
          self.myChart = window.echarts.init(el);
          if (self.onResize) self.onResize();
          if (self.onDataUpdated) self.onDataUpdated();
        }
      }, 200);
    }
  });
};

self.setupHoverSync = function() {
  var container = self.ctx.$container ? self.ctx.$container[0] : null;
  if (!container) return;
  var wrapper = container.querySelector('.chart-wrapper');
  if (wrapper && !self.hasHoverBound) {
    self.hasHoverBound = true;
    wrapper.addEventListener('mouseleave', function() {
      self.restoreDefaultCards();
    });
  }
};

self.onResize = function() {
  if (self.myChart) {
    self.myChart.resize();
  } else {
    self.initChart();
  }
};

self.restoreDefaultCards = function() {
  var container = self.ctx.$container ? self.ctx.$container[0] : null;
  if (!container || !self.cardMetrics) return;

  var m = self.cardMetrics;
  var elSolar = container.querySelector('#solar-live-val');
  var elSolarSub = container.querySelector('#solar-sub-val');
  var elLoad = container.querySelector('#load-live-val');
  var elLoadSub = container.querySelector('#load-sub-val');
  var elBess = container.querySelector('#bess-live-val');
  var elBessSub = container.querySelector('#bess-sub-val');

  if (elSolar) elSolar.textContent = m.solar.primary.toFixed(1);
  if (elSolarSub) elSolarSub.textContent = m.solar.sub;

  if (elLoad) elLoad.textContent = m.load.primary.toFixed(1);
  if (elLoadSub) elLoadSub.textContent = m.load.sub;

  if (elBess) elBess.textContent = m.bess.primary.toFixed(1);
  if (elBessSub) elBessSub.textContent = m.bess.sub;
};

self.onHoverPoint = function(params) {
  var container = self.ctx.$container ? self.ctx.$container[0] : null;
  if (!container || !params || params.length === 0) return;

  var d = new Date(params[0].value[0]);
  var months = ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'];
  var timeStr = months[d.getMonth()] + ' ' + d.getDate() + ' ' + d.toTimeString().split(' ')[0].substring(0, 5);

  var sVal = null, lVal = null, bVal = null;
  for (var i = 0; i < params.length; i++) {
    var p = params[i];
    var sName = p.seriesName || '';
    if (sName.indexOf('Solar') !== -1) sVal = parseFloat(p.value[1]);
    else if (sName.indexOf('Carga') !== -1) lVal = parseFloat(p.value[1]);
    else if (sName.indexOf('BESS') !== -1) bVal = parseFloat(p.value[1]);
  }

  var elSolar = container.querySelector('#solar-live-val');
  var elSolarSub = container.querySelector('#solar-sub-val');
  var elLoad = container.querySelector('#load-live-val');
  var elLoadSub = container.querySelector('#load-sub-val');
  var elBess = container.querySelector('#bess-live-val');
  var elBessSub = container.querySelector('#bess-sub-val');

  if (sVal !== null && elSolar) {
    elSolar.textContent = sVal.toFixed(1);
    if (elSolarSub) elSolarSub.textContent = timeStr;
  }
  if (lVal !== null && elLoad) {
    elLoad.textContent = lVal.toFixed(1);
    if (elLoadSub) elLoadSub.textContent = timeStr;
  }
  if (bVal !== null && elBess) {
    elBess.textContent = bVal.toFixed(1);
    if (elBessSub) elBessSub.textContent = timeStr;
  }
};

// Zero-Phase Centered Adaptive Smoothing Filter
self.smoothSeries = function(pts, targetWindow) {
  if (!pts || pts.length <= 5) return pts;
  var w = targetWindow || 15;
  if (pts.length < 150) w = 3;
  else if (pts.length < 600) w = 7;
  else if (pts.length < 1800) w = 15;
  else w = 21;

  var half = Math.floor(w / 2);
  var res = [];
  for (var i = 0; i < pts.length; i++) {
    var sum = 0, count = 0;
    var start = Math.max(0, i - half);
    var end = Math.min(pts.length - 1, i + half);
    for (var j = start; j <= end; j++) {
      sum += pts[j][1];
      count++;
    }
    res.push([pts[i][0], Math.round((sum / count) * 10) / 10]);
  }
  return res;
};

self.onDataUpdated = function() {
  var data = self.ctx.data || [];
  var rawSolar = [], rawLoad = [], rawBess = [];
  var sVals = [], lVals = [], bVals = [];

  for (var i = 0; i < data.length; i++) {
    var item = data[i];
    var pts = item.data || [];
    var k = (item.dataKey.name || item.dataKey.label || '').toLowerCase();

    if (pts.length > 0) {
      if (k.indexOf('solar') !== -1) {
        rawSolar = pts.map(function(p) { return [p[0], parseFloat(p[1]) || 0]; });
        sVals = pts.map(function(p) { return parseFloat(p[1]) || 0; });
      } else if (k.indexOf('carga') !== -1 || k.indexOf('load') !== -1 || k.indexOf('demanda') !== -1) {
        rawLoad = pts.map(function(p) { return [p[0], parseFloat(p[1]) || 0]; });
        lVals = pts.map(function(p) { return parseFloat(p[1]) || 0; });
      } else if (k.indexOf('bess') !== -1) {
        rawBess = pts.map(function(p) { return [p[0], parseFloat(p[1]) || 0]; });
        bVals = pts.map(function(p) { return parseFloat(p[1]) || 0; });
      }
    }
  }

  // Sort ascending chronologically
  rawSolar.sort(function(a, b) { return a[0] - b[0]; });
  rawLoad.sort(function(a, b) { return a[0] - b[0]; });
  rawBess.sort(function(a, b) { return a[0] - b[0]; });

  // Calculate statistics (Exact Average & Max)
  var calcStats = function(arr, fallbackLast) {
    if (!arr || arr.length === 0) return { avg: fallbackLast, max: fallbackLast, last: fallbackLast };
    var sum = 0, max = arr[0];
    for (var j = 0; j < arr.length; j++) {
      var val = arr[j];
      sum += val;
      if (val > max) max = val;
    }
    return {
      avg: sum / arr.length,
      max: max,
      last: arr[arr.length - 1]
    };
  };

  var sStats = calcStats(sVals, 0.0);
  var lStats = calcStats(lVals, 420.0);
  var bStats = calcStats(bVals, 435.0);

  var isHistorical = false;
  if (self.ctx.timeWindow) {
    if (self.ctx.timeWindow.isRealtime === false) isHistorical = true;
    else if (self.ctx.timeWindow.realtime && self.ctx.timeWindow.realtime.timewindowMs > 3600000 * 12) isHistorical = true;
  }

  if (isHistorical) {
    self.cardMetrics = {
      solar: { primary: sStats.avg, sub: 'Pico: ' + sStats.max.toFixed(1) + ' kW' },
      load: { primary: lStats.avg, sub: 'Pico: ' + lStats.max.toFixed(1) + ' kW' },
      bess: { primary: bStats.avg, sub: 'Pico: ' + bStats.max.toFixed(1) + ' kW' }
    };
  } else {
    self.cardMetrics = {
      solar: { primary: sStats.last, sub: 'Pico: ' + sStats.max.toFixed(1) + ' kW' },
      load: { primary: lStats.last, sub: 'Pico: ' + lStats.max.toFixed(1) + ' kW' },
      bess: { primary: bStats.last, sub: 'Pico: ' + bStats.max.toFixed(1) + ' kW' }
    };
  }

  self.restoreDefaultCards();

  // Status update
  var container = self.ctx.$container ? self.ctx.$container[0] : null;
  if (container) {
    var elStatus = container.querySelector('#solar-balance-status');
    if (elStatus) {
      if (sStats.last > lStats.last) {
        elStatus.innerHTML = '<span style="color:#64B856;">Excedente Solar · Inyectando a BESS (' + (sStats.last - lStats.last).toFixed(1) + ' kW)</span>';
      } else {
        elStatus.innerHTML = '<span style="color:#38bdf8;">Soporte BESS a Carga (' + (lStats.last - sStats.last).toFixed(1) + ' kW)</span>';
      }
    }
  }

  if (!self.myChart) {
    self.initChart();
  }
  if (!self.myChart) return;

  var cleanSolar = self.smoothSeries(rawSolar, 15);
  var cleanLoad = self.smoothSeries(rawLoad, 15);
  var cleanBess = self.smoothSeries(rawBess, 15);

  var monthsShort = ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'];

  var option = {
    backgroundColor: 'transparent',
    tooltip: {
      trigger: 'axis',
      confine: true,
      alwaysShowContent: false,
      hideDelay: 500,
      extraCssText: 'z-index: 999999; box-shadow: 0 4px 20px rgba(0,0,0,0.7); pointer-events: none;',
      backgroundColor: 'rgba(15, 23, 42, 0.95)',
      borderColor: 'rgba(100, 184, 86, 0.4)',
      borderWidth: 1,
      padding: [8, 12],
      textStyle: { color: '#f8fafc', fontSize: 11 },
      axisPointer: {
        type: 'line',
        snap: true,
        lineStyle: { color: 'rgba(255, 255, 255, 0.4)', width: 1.5, type: 'dashed' }
      },
      formatter: function(params) {
        if (!params || params.length === 0) return '';
        self.onHoverPoint(params);
        var d = new Date(params[0].value[0]);
        var timeStr = monthsShort[d.getMonth()] + ' ' + d.getDate() + ', ' + d.toTimeString().split(' ')[0];
        var out = '<div style="font-weight:700; margin-bottom:5px; color:#F59E0B; border-bottom:1px solid rgba(255,255,255,0.1); padding-bottom:3px;">📅 ' + timeStr + '</div>';
        params.forEach(function(p) {
          out += '<div style="display:flex; justify-content:space-between; gap:16px; margin: 3px 0;">' +
                 '<span>' + p.marker + ' ' + p.seriesName + ':</span>' +
                 '<strong style="color:#ffffff;">' + p.value[1] + ' kW</strong>' +
                 '</div>';
        });
        return out;
      }
    },
    grid: {
      left: 50,
      right: 25,
      top: 15,
      bottom: 28,
      containLabel: false
    },
    dataZoom: [
      {
        type: 'slider',
        show: true,
        bottom: 2,
        height: 18,
        borderColor: 'rgba(100, 184, 86, 0.3)',
        backgroundColor: 'rgba(14, 25, 16, 0.7)',
        fillerColor: 'rgba(245, 158, 11, 0.22)',
        handleStyle: { color: '#F59E0B', borderColor: '#EAB308' },
        moveHandleStyle: { color: 'rgba(245, 158, 11, 0.4)' },
        showDetail: true,
        showDataShadow: true,
        dataBackground: {
          lineStyle: { color: '#F59E0B', width: 1 },
          areaStyle: { color: 'rgba(245, 158, 11, 0.25)' }
        },
        selectedDataBackground: {
          lineStyle: { color: '#64B856', width: 1 },
          areaStyle: { color: 'rgba(100, 184, 86, 0.4)' }
        },
        textStyle: { color: '#94a3b8', fontSize: 9 }
      },
      {
        type: 'inside'
      }
    ],
    xAxis: {
      type: 'time',
      axisLine: { lineStyle: { color: 'rgba(100, 184, 86, 0.25)' } },
      axisTick: { show: true, lineStyle: { color: 'rgba(100, 184, 86, 0.25)' } },
      splitLine: { show: false },
      axisLabel: {
        color: '#94a3b8',
        fontSize: 10,
        formatter: function(val) {
          var d = new Date(val);
          var hh = d.getHours();
          var mm = d.getMinutes();
          if (hh === 0 && mm === 0) {
            return '{dayBadge|' + monthsShort[d.getMonth()] + ' ' + d.getDate() + '}';
          }
          return String(hh).padStart(2, '0') + ':' + String(mm).padStart(2, '0');
        },
        rich: {
          dayBadge: {
            color: '#ffffff',
            fontWeight: 'bold',
            fontSize: 10,
            backgroundColor: 'rgba(30, 41, 59, 0.9)',
            borderColor: 'rgba(245, 158, 11, 0.5)',
            borderWidth: 1,
            padding: [2, 6],
            borderRadius: 3
          }
        }
      }
    },
    yAxis: {
      type: 'value',
      scale: true,
      axisLine: { show: false },
      axisLabel: { color: '#94a3b8', fontSize: 10, formatter: '{value} kW' },
      splitLine: { lineStyle: { color: 'rgba(255, 255, 255, 0.05)' } }
    },
    series: [
      {
        name: 'Solar Total',
        type: 'line',
        data: cleanSolar,
        smooth: 0.35,
        showSymbol: false,
        lineStyle: { color: '#F59E0B', width: 2.2 },
        itemStyle: { color: '#F59E0B' },
        areaStyle: {
          color: {
            type: 'linear',
            x: 0, y: 0, x2: 0, y2: 1,
            colorStops: [
              { offset: 0, color: 'rgba(245, 158, 11, 0.40)' },
              { offset: 1, color: 'rgba(245, 158, 11, 0.02)' }
            ]
          }
        }
      },
      {
        name: 'Demanda Carga',
        type: 'line',
        data: cleanLoad,
        smooth: 0.30,
        showSymbol: false,
        lineStyle: { color: '#FFFFFF', width: 2.2 },
        itemStyle: { color: '#FFFFFF' }
      },
      {
        name: 'Potencia BESS',
        type: 'line',
        data: cleanBess,
        smooth: 0.35,
        showSymbol: false,
        lineStyle: { color: '#A855F7', width: 2.0 },
        itemStyle: { color: '#A855F7' },
        areaStyle: {
          color: {
            type: 'linear',
            x: 0, y: 0, x2: 0, y2: 1,
            colorStops: [
              { offset: 0, color: 'rgba(168, 85, 247, 0.22)' },
              { offset: 1, color: 'rgba(168, 85, 247, 0.01)' }
            ]
          }
        }
      }
    ]
  };

  self.myChart.setOption(option, true);
};

self.onDestroy = function() {
  if (self.myChart) {
    self.myChart.dispose();
    self.myChart = null;
  }
};
